# ============================================================================
# install_techtoon_streamlit.ps1
# Bulletproof installer - writes app.py, utils\math_eval.py, pages\cash_boxes.py
# using BASE64-decoded UTF-8 (no BOM). No string replacement, no parse risk,
# no encoding issues. Idempotent - safe to re-run.
#
# Usage (PowerShell, any version 5.1+):
#     .\install_techtoon_streamlit.ps1
# ============================================================================
$ErrorActionPreference = "Stop"
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

$dest = "D:\PROG\Accounting Prog\Techtoon Accounting C+\Techtoon.Streamlit"
if (-not (Test-Path $dest)) {
    Write-Host "Target folder not found: $dest" -ForegroundColor Red
    Write-Host "Create it first or edit `$dest in this script." -ForegroundColor Yellow
    exit 1
}

# Ensure subfolders exist
foreach ($sub in @("utils", "pages")) {
    $p = Join-Path $dest $sub
    if (-not (Test-Path $p)) { New-Item -ItemType Directory -Path $p | Out-Null }
}

function Write-FileFromBase64($relativePath, $b64) {
    $full = Join-Path $dest $relativePath
    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host ("  wrote {0}  ({1} bytes)" -f $relativePath, $bytes.Length) -ForegroundColor Green
}

Write-Host "Installing Techtoon Streamlit files into:" -ForegroundColor Cyan
Write-Host "  $dest" -ForegroundColor DarkGray
Write-Host ""

# --- app.py ---
$b64 = ""
Write-FileFromBase64 "app.py" $b64

# --- utils\math_eval.py ---
$b64 = ""
Write-FileFromBase64 "utils\math_eval.py" $b64

# --- pages\cash_boxes.py ---
$b64 = ""
Write-FileFromBase64 "pages\cash_boxes.py" $b64

Write-Host ""
Write-Host "=== All files installed. ===" -ForegroundColor Green
Write-Host ""
Write-Host "Next:" -ForegroundColor Cyan
Write-Host "  cd `"$dest`"" -ForegroundColor White
Write-Host "  streamlit run app.py" -ForegroundColor White
Write-Host ""
Write-Host "Then commit + push to GitHub:" -ForegroundColor Cyan
Write-Host "  git add . && git commit -m `"Add cash boxes page + dynamic balances + expression eval`" && git push" -ForegroundColor White
